	benchNFlag   int
	benchCFlag   int
	bodyFlag     string
	formFlag     bool
	jsonFlag     bool
	prettyFlag   bool
	insecureFlag bool
	proxyFlag    string
	printFlag    string
	versionFlag  bool
	downloadFlag bool
)

func init() {
	flag.StringVar(&authFlag, "auth", "", "")
	flag.StringVar(&authFlag, "a", "", "")
	flag.BoolVar(&benchFlag, "bench", false, "")
	flag.BoolVar(&benchFlag, "b", false, "")
	flag.IntVar(&benchNFlag, "b.N", 1000, "")
	flag.IntVar(&benchCFlag, "b.C", 100, "")
	flag.StringVar(&bodyFlag, "body", "", "")
	flag.BoolVar(&formFlag, "form", false, "")
	flag.BoolVar(&formFlag, "f", false, "")
	flag.BoolVar(&jsonFlag, "json", true, "")
	flag.BoolVar(&jsonFlag, "j", true, "")
	flag.BoolVar(&prettyFlag, "pretty", true, "")
	flag.BoolVar(&prettyFlag, "p", true, "")
	flag.BoolVar(&insecureFlag, "insecure", false, "")
	flag.BoolVar(&insecureFlag, "i", false, "")
	flag.StringVar(&proxyFlag, "proxy", "", "")
	flag.StringVar(&printFlag, "print", "A", "")
	flag.BoolVar(&versionFlag, "version", false, "")
	flag.BoolVar(&versionFlag, "v", false, "")
	flag.BoolVar(&downloadFlag, "download", false, "")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat
`)
