					if err != nil {
						log.Fatalf("can't read file %s: %v", val[1:], err)
					}
					val = string(content)
				}
				data[key] = val
				hasData = true
			}
		} else if idx := strings.Index(item, "@"); idx != -1 {
			key := item[:idx]
			filename := item[idx+1:]
			content, err := ioutil.ReadFile(filename)
			if err != nil {
				log.Fatalf("can't read file %s: %v", filename, err)
			}
			data[key] = string(content)
			hasData = true
		}
	}

	if method == "" {
		if hasData || bodyFlag != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	parsedURL.RawQuery = queryParams.Encode()

	var bodyBytes []byte
	contentType := ""

	if bodyFlag != "" {
		bodyBytes = []byte(bodyFlag)
	} else if len(data) > 0 {
		if formFlag {
			form := url.Values{}
			for k, v := range data {
				form.Set(k, v)
			}
			bodyBytes = []byte(form.Encode())
			contentType = "application/x-www-form-urlencoded"
		} else {
			jsonBytes, _ := json.Marshal(data)
			bodyBytes = jsonBytes
			contentType = "application/json"
		}
	}

	req, err := http.NewRequest(method, parsedURL.String(), bytes.NewReader(bodyBytes))
	if err != nil {
		log.Fatalf("can't create request: %v", err)
	}

	for k, v := range headers {
		req.Header[k] = v
	}

	if authFlag != "" {
		parts := strings.SplitN(authFlag, ":", 2)
		user := parts[0]
		pass := ""
		if len(parts) > 1 {
			pass = parts[1]
		}
		req.SetBasicAuth(user, pass)
	}

	if req.Header.Get("User-Agent") == "" {
		req.Header.Set("User-Agent", "bat/0.1.0")
	}
	if req.Header.Get("Accept") == "" {
		req.Header.Set("Accept", "application/json")
	}
	if contentType != "" && req.Header.Get("Content-Type") == "" {
		req.Header.Set("Content-Type", contentType)
	}

	transport := &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: insecureFlag},
	}
	if proxyFlag != "" {
		proxyURL, err := url.Parse(proxyFlag)
		if err != nil {
			log.Fatalf("can't parse proxy url: %v", err)
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}

	client := &http.Client{
		Transport: transport,
	}

	if benchFlag {
		runBench(req, benchNFlag, benchCFlag)
		return
	}

	if downloadFlag {
		doDownload(client, req)
		return
	}

	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %s: %v", method, err)
	}
	defer resp.Body.Close()

	printAll(req, bodyBytes, resp, printFlag, prettyFlag)
}

func printAll(req *http.Request, reqBody []byte, resp *http.Response, printFlag string, pretty bool) {
	isTTY := false
	fileInfo, _ := os.Stdout.Stat()
	if (fileInfo.Mode() & os.ModeCharDevice) != 0 {
		isTTY = true
	}

	if !isTTY {
		body, _ := ioutil.ReadAll(resp.Body)
		fmt.Print(string(body))
		return
	}

	showReqHeaders := strings.ContainsAny(printFlag, "AH")
	showReqBody := strings.ContainsAny(printFlag, "AB")
	showRespHeaders := strings.ContainsAny(printFlag, "Ah")
	showRespBody := strings.ContainsAny(printFlag, "Ab")

	if showReqHeaders {
		fmt.Printf("\033[95m%s\033[0m \033[96m%s\033[0m \033[95m%s\033[0m\r\n", req.Method, req.URL.RequestURI(), req.Proto)
		var keys []string
		for k := range req.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("\033[90m%s\033[0m: \033[96m%s\033[0m\r\n", k, strings.Join(req.Header[k], ", "))
		}
		fmt.Print("\r\n")
	}

	if showReqBody && len(reqBody) > 0 {
		fmt.Print("\r\n")
		fmt.Print(string(reqBody))
		fmt.Print("\r\n\r\n")
	}

	if showRespHeaders {
		fmt.Printf("\033[95m%s\033[0m \033[92m%s\033[0m\r\n", resp.Proto, resp.Status)
		var keys []string
		for k := range resp.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("\033[90m%s\033[0m: \033[96m%s\033[0m\r\n", k, strings.Join(resp.Header[k], ", "))
		}
		fmt.Print("\r\n")
	}

	if showRespBody {
		body, _ := ioutil.ReadAll(resp.Body)
		if pretty && strings.Contains(resp.Header.Get("Content-Type"), "application/json") {
			var obj interface{}
			if err := json.Unmarshal(body, &obj); err == nil {
				prettyJSON, _ := json.MarshalIndent(obj, "", "  ")
				fmt.Print(colorizeJSON(string(prettyJSON)))
				fmt.Print("\r\n")
			} else {
				fmt.Printf("\033[92m%s\033[0m\r\n", string(body))
			}
		} else {
			fmt.Printf("\033[92m%s\033[0m\r\n", string(body))
		}
	}
}

func colorizeJSON(j string) string {
	var res strings.Builder
	lines := strings.Split(j, "\n")
	for i, line := range lines {
		if idx := strings.Index(line, "\""); idx != -1 {
			colonIdx := strings.Index(line, ":")
			if colonIdx != -1 && idx < colonIdx {
				res.WriteString(line[:idx])
				res.WriteString("\033[95m")
				endKey := strings.Index(line[idx+1:], "\"")
				res.WriteString(line[idx : idx+endKey+2])
				res.WriteString("\033[0m")
				rest := line[idx+endKey+2:]
				colonIdxInRest := strings.Index(rest, ":")
				res.WriteString(rest[:colonIdxInRest+1])
				valPart := rest[colonIdxInRest+1:]
				if vIdx := strings.Index(valPart, "\""); vIdx != -1 {
					vEnd := strings.LastIndex(valPart, "\"")
					res.WriteString(valPart[:vIdx])
					res.WriteString("\033[96m")
					res.WriteString(valPart[vIdx : vEnd+1])
					res.WriteString("\033[0m")
					res.WriteString(valPart[vEnd+1:])
				} else {
					res.WriteString(valPart)
				}
			} else {
				if vIdx := strings.Index(line, "\""); vIdx != -1 {
					vEnd := strings.LastIndex(line, "\"")
					res.WriteString(line[:vIdx])
					res.WriteString("\033[96m")
					res.WriteString(line[vIdx : vEnd+1])
					res.WriteString("\033[0m")
					res.WriteString(line[vEnd+1:])
				} else {
					res.WriteString(line)
				}
			}
		} else {
			res.WriteString(line)
		}
		if i < len(lines)-1 {
			res.WriteString("\r\n")
		}
	}
	return res.String()
}

func doDownload(client *http.Client, req *http.Request) {
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %s: %v", req.Method, err)
	}
	defer resp.Body.Close()

	fmt.Printf("\033[95m%s\033[0m \033[92m%s\033[0m\r\n", resp.Proto, resp.Status)
	var keys []string
	for k := range resp.Header {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Printf("\033[90m%s\033[0m : \033[96m%s\033[0m\r\n", k, strings.Join(resp.Header[k], ", "))
	}
	fmt.Print("\r\n")

	filename := "index.html"
	if req.URL.Path != "" && req.URL.Path != "/" {
		parts := strings.Split(req.URL.Path, "/")
		filename = parts[len(parts)-1]
		if filename == "" {
			filename = "index.html"
		}
	}
	fmt.Printf("Downloading to \"%s\"\n", filename)

	out, err := os.Create(filename)
	if err != nil {
		log.Fatalf("can't create file: %v", err)
	}
	defer out.Close()

	contentLength := resp.ContentLength
	buf := &newWriter{total: contentLength, filename: filename, startTime: time.Now()}
	io.Copy(out, io.TeeReader(resp.Body, buf))
	fmt.Println()
}

type newWriter struct {
	total     int64
	current   int64
	filename  string
	startTime time.Time
}

func (w *newWriter) Write(p []byte) (int, error) {
	n := len(p)
	w.current += int64(n)
	w.printProgress()
	return n, nil
}

func (w *newWriter) printProgress() {
	if w.total <= 0 {
		return
	}
	percent := float64(w.current) * 100 / float64(w.total)
	elapsed := time.Since(w.startTime).Seconds()
	speed := float64(w.current) / 1024 / (elapsed + 0.0001)
	barLen := 85
	completed := int(float64(barLen) * float64(w.current) / float64(w.total))
	if completed > barLen {
		completed = barLen
	}
	bar := strings.Repeat("=", completed) + strings.Repeat(" ", barLen-completed)
	fmt.Printf("\r%d B / %d B [%s] %.2f %% %.2f KB/s 0s", w.current, w.total, bar, percent, speed)
}

type benchResult struct {
	duration   time.Duration
	statusCode int
	size       int64
	err        error
}

func runBench(req *http.Request, n, c int) {
	results := make(chan benchResult, n)
	start := time.Now()

	for i := 0; i < c; i++ {
		go func() {
			for j := 0; j < n/c; j++ {
				results <- doReq(req)
			}
		}()
	}
	if n%c != 0 {
		go func() {
			for j := 0; j < n%c; j++ {
				results <- doReq(req)
			}
		}()
	}

	var times []float64
	statusCodes := make(map[int]int)
	var totalSize int64
	errorMap := make(map[string]int)

	for i := 0; i < n; i++ {
		res := <-results
		if res.err != nil {
			errorMap[res.err.Error()]++
		} else {
			times = append(times, res.duration.Seconds())
			statusCodes[res.statusCode]++
			totalSize += res.size
		}
	}

	totalTime := time.Since(start).Seconds()
	sort.Float64s(times)

	fmt.Printf("\nSummary:\n")
	fmt.Printf("  Total:\t%.4f secs.\n", totalTime)
	if len(times) > 0 {
		var sum float64
		for _, t := range times {
			sum += t
		}
		fmt.Printf("  Slowest:\t%.4f secs.\n", times[len(times)-1])
		fmt.Printf("  Fastest:\t%.4f secs.\n", times[0])
		fmt.Printf("  Average:\t%.4f secs.\n", sum/float64(len(times)))
		fmt.Printf("  Requests/sec:\t%.4f\n", float64(len(times))/totalTime)
		fmt.Printf("  Total Data Received:\t%d bytes.\n", totalSize)
		fmt.Printf("  Response Size per Request:\t%d bytes.\n", totalSize/int64(len(times)))
	}

	if len(statusCodes) > 0 {
		fmt.Printf("\nStatus code distribution:\n")
		var keys []int
		for k := range statusCodes {
			keys = append(keys, k)
		}
		sort.Ints(keys)
		for _, k := range keys {
			fmt.Printf("  [%d]\t%d responses\n", k, statusCodes[k])
		}
	}

	if len(times) > 0 {
		fmt.Printf("\nResponse time histogram:\n")
		min := times[0]
		max := times[len(times)-1]
		bucketSize := (max - min) / 10
		if bucketSize == 0 {
			bucketSize = 0.001
		}
		buckets := make([]int, 11)
		for _, t := range times {
			idx := int((t - min) / bucketSize)
			if idx > 10 {
				idx = 10
			}
			buckets[idx]++
		}
		maxBucket := 0
		for _, b := range buckets {
			if b > maxBucket {
				maxBucket = b
			}
		}
		for i, b := range buckets {
			barLen := 0
			if maxBucket > 0 {
				barLen = (b * 40) / maxBucket
			}
			fmt.Printf("  %.3f [%d]\t|%s\n", min+float64(i)*bucketSize, b, strings.Repeat("∎", barLen))
		}

		fmt.Printf("\nLatency distribution:\n")
		percentiles := []int{10, 25, 50, 75, 90}
		for _, p := range percentiles {
			idx := (p * len(times)) / 100
			if idx >= len(times) {
				idx = len(times) - 1
			}
			fmt.Printf("  %d%% in %.4f secs.\n", p, times[idx])
		}
	}

	if len(errorMap) > 0 {
		fmt.Printf("\nError distribution:\n")
		var keys []string
		for k := range errorMap {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("  [%d]\t%s\n", errorMap[k], k)
		}
	}
}

func doReq(req *http.Request) benchResult {
	// Re-creating the request to avoid race condition on headers
	newReq, _ := http.NewRequest(req.Method, req.URL.String(), nil)
	newReq.Header = make(http.Header)
	for k, v := range req.Header {
		newReq.Header[k] = v
	}
	// We don't support body in bench for now to keep it simple, 
	// though original might.

	start := time.Now()
	client := &http.Client{}
	resp, err := client.Do(newReq)
	duration := time.Since(start)
	if err != nil {
		return benchResult{err: err}
	}
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	return benchResult{
		duration:   duration,
		statusCode: resp.StatusCode,
		size:       int64(len(body)),
	}
}
