actions.command:
cat <<'EOF' > bat.go
package main

import (
	"bytes"
	"crypto/tls"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"io/ioutil"
	"log"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strings"
	"time"
)

var (
	authFlag     string
	benchFlag    bool
	benchNFlag   int
	benchCFlag   int
	bodyFlag     string
	formFlag     bool
	jsonFlag     bool
	prettyFlag   bool
	insecureFlag bool
	proxyFlag    string
	printFlag    string
	versionFlag  bool
	downloadFlag bool
)

func init() {
	flag.StringVar(&authFlag, "auth", "", "")
	flag.StringVar(&authFlag, "a", "", "")
	flag.BoolVar(&benchFlag, "bench", false, "")
	flag.BoolVar(&benchFlag, "b", false, "")
	flag.IntVar(&benchNFlag, "b.N", 1000, "")
	flag.IntVar(&benchCFlag, "b.C", 100, "")
	flag.StringVar(&bodyFlag, "body", "", "")
	flag.BoolVar(&formFlag, "form", false, "")
	flag.BoolVar(&formFlag, "f", false, "")
	flag.BoolVar(&jsonFlag, "json", true, "")
	flag.BoolVar(&jsonFlag, "j", true, "")
	flag.BoolVar(&prettyFlag, "pretty", true, "")
	flag.BoolVar(&prettyFlag, "p", true, "")
	flag.BoolVar(&insecureFlag, "insecure", false, "")
	flag.BoolVar(&insecureFlag, "i", false, "")
	flag.StringVar(&proxyFlag, "proxy", "", "")
	flag.StringVar(&printFlag, "print", "A", "")
	flag.BoolVar(&versionFlag, "version", false, "")
	flag.BoolVar(&versionFlag, "v", false, "")
	flag.BoolVar(&downloadFlag, "download", false, "")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat
`)
	}
}

func main() {
	log.SetFlags(log.LstdFlags | log.Lshortfile)
	flag.Parse()

	if versionFlag {
		fmt.Println("Version: 0.1.0")
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	methods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true,
		"HEAD": true, "OPTIONS": true, "PATCH": true, "TRACE": true,
	}

	var method, urlStr string
	var itemArgs []string

	if methods[strings.ToUpper(args[0])] {
		method = strings.ToUpper(args[0])
		if len(args) < 2 {
			flag.Usage()
			os.Exit(2)
		}
		urlStr = args[1]
		itemArgs = args[2:]
	} else {
		urlStr = args[0]
		itemArgs = args[1:]
	}

	if !strings.HasPrefix(urlStr, "http://") && !strings.HasPrefix(urlStr, "https://") {
		urlStr = "http://" + urlStr
	}

	parsedURL, err := url.Parse(urlStr)
	if err != nil {
		log.Fatalf("can't parse the url: %v", err)
	}

	headers := make(http.Header)
	data := make(map[string]string)
	queryParams := parsedURL.Query()

	hasData := false
	for _, item := range itemArgs {
		if idx := strings.Index(item, ":"); idx != -1 && (strings.Index(item, "=") == -1 || idx < strings.Index(item, "=")) {
			headers.Set(strings.TrimSpace(item[:idx]), strings.TrimSpace(item[idx+1:]))
		} else if idx := strings.Index(item, "="); idx != -1 {
			key := item[:idx]
			val := item[idx+1:]
			if method == "GET" {
				queryParams.Add(key, val)
			} else {
				if strings.HasPrefix(val, "@") {
					content, err := ioutil.ReadFile(val[1:])
					if err != nil {
						log.Fatalf("can't read file %s: %v", val[1:], err)
					}
					val = string(content)
				}
				data[key] = val
				hasData = true
			}
		} else if idx := strings.Index(item, "@"); idx != -1 {
			key := item[:idx]
			filename := item[idx+1:]
			content, err := ioutil.ReadFile(filename)
			if err != nil {
				log.Fatalf("can't read file %s: %v", filename, err)
			}
			data[key] = string(content)
			hasData = true
		}
	}

	if method == "" {
		if hasData || bodyFlag != "" {
			method = "POST"
		} else {
			method = "GET"
		}
	}

	parsedURL.RawQuery = queryParams.Encode()

	var bodyBytes []byte
	contentType := ""

	if bodyFlag != "" {
		bodyBytes = []byte(bodyFlag)
	} else if len(data) > 0 {
		if formFlag {
			form := url.Values{}
			for k, v := range data {
				form.Set(k, v)
			}
			bodyBytes = []byte(form.Encode())
			contentType = "application/x-www-form-urlencoded"
		} else {
			jsonBytes, _ := json.Marshal(data)
			bodyBytes = jsonBytes
			contentType = "application/json"
		}
	}

	req, err := http.NewRequest(method, parsedURL.String(), bytes.NewReader(bodyBytes))
	if err != nil {
		log.Fatalf("can't create request: %v", err)
	}

	for k, v := range headers {
		req.Header[k] = v
	}

	if authFlag != "" {
		parts := strings.SplitN(authFlag, ":", 2)
		user := parts[0]
		pass := ""
		if len(parts) > 1 {
			pass = parts[1]
		}
		req.SetBasicAuth(user, pass)
	}

	if req.Header.Get("User-Agent") == "" {
		req.Header.Set("User-Agent", "bat/0.1.0")
	}
	if req.Header.Get("Accept") == "" {
		req.Header.Set("Accept", "application/json")
	}
	if contentType != "" && req.Header.Get("Content-Type") == "" {
		req.Header.Set("Content-Type", contentType)
	}

	if benchFlag {
		runBench(req, bodyBytes, benchNFlag, benchCFlag)
		return
	}

	transport := &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: insecureFlag},
	}
	if proxyFlag != "" {
		proxyURL, err := url.Parse(proxyFlag)
		if err != nil {
			log.Fatalf("can't parse proxy url: %v", err)
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}

	client := &http.Client{
		Transport: transport,
	}

	if downloadFlag {
		doDownload(client, req)
		return
	}

	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %v", err)
	}
	defer resp.Body.Close()

	printAll(req, bodyBytes, resp, printFlag, prettyFlag)
}

func printAll(req *http.Request, reqBody []byte, resp *http.Response, printFlag string, pretty bool) {
	isTTY := false
	fileInfo, _ := os.Stdout.Stat()
	if (fileInfo.Mode() & os.ModeCharDevice) != 0 {
		isTTY = true
	}

	if !isTTY {
		body, _ := ioutil.ReadAll(resp.Body)
		fmt.Print(string(body))
		return
	}

	showReqHeaders := strings.ContainsAny(printFlag, "AH")
	showReqBody := strings.ContainsAny(printFlag, "AB")
	showRespHeaders := strings.ContainsAny(printFlag, "Ah")
	showRespBody := strings.ContainsAny(printFlag, "Ab")

	if showReqHeaders {
		fmt.Printf("\033[95m%s\033[0m \033[96m%s\033[0m \033[95m%s\033[0m\r\n", req.Method, req.URL.RequestURI(), req.Proto)
		var keys []string
		for k := range req.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("\033[90m%s\033[0m: \033[96m%s\033[0m\r\n", k, strings.Join(req.Header[k], ", "))
		}
		fmt.Print("\r\n")
	}

	if showReqBody && len(reqBody) > 0 {
		fmt.Print("\r\n")
		fmt.Print(string(reqBody))
		fmt.Print("\r\n\r\n")
	}

	if showRespHeaders {
		fmt.Printf("\033[95m%s\033[0m \033[92m%s\033[0m\r\n", resp.Proto, resp.Status)
		var keys []string
		for k := range resp.Header {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			fmt.Printf("\033[90m%s\033[0m: \033[96m%s\033[0m\r\n", k, strings.Join(resp.Header[k], ", "))
		}
		fmt.Print("\r\n")
	}

	if showRespBody {
		body, _ := ioutil.ReadAll(resp.Body)
		if pretty && strings.Contains(resp.Header.Get("Content-Type"), "application/json") {
			var obj interface{}
			if err := json.Unmarshal(body, &obj); err == nil {
				prettyJSON, _ := json.MarshalIndent(obj, "", "  ")
				fmt.Print(colorizeJSON(string(prettyJSON)))
				fmt.Print("\r\n")
			} else {
				fmt.Printf("\033[92m%s\033[0m\r\n", string(body))
			}
		} else {
			fmt.Printf("\033[92m%s\033[0m\r\n", string(body))
		}
	}
}

func colorizeJSON(j string) string {
	var res strings.Builder
	lines := strings.Split(j, "\n")
	for i, line := range lines {
		if idx := strings.Index(line, "\""); idx != -1 {
			colonIdx := strings.Index(line, ":")
			if colonIdx != -1 && idx < colonIdx {
				res.WriteString(line[:idx])
				res.WriteString("\033[95m")
				endKey := strings.Index(line[idx+1:], "\"")
				res.WriteString(line[idx : idx+endKey+2])
				res.WriteString("\033[0m")
				rest := line[idx+endKey+2:]
				colonIdxInRest := strings.Index(rest, ":")
				res.WriteString(rest[:colonIdxInRest+1])
				valPart := rest[colonIdxInRest+1:]
				if vIdx := strings.Index(valPart, "\""); vIdx != -1 {
					vEnd := strings.LastIndex(valPart, "\"")
					res.WriteString(valPart[:vIdx])
					res.WriteString("\033[96m")
					res.WriteString(valPart[vIdx : vEnd+1])
					res.WriteString("\033[0m")
					res.WriteString(valPart[vEnd+1:])
				} else {
					res.WriteString(valPart)
				}
			} else {
				if vIdx := strings.Index(line, "\""); vIdx != -1 {
					vEnd := strings.LastIndex(line, "\"")
					res.WriteString(line[:vIdx])
					res.WriteString("\033[96m")
					res.WriteString(line[vIdx : vEnd+1])
					res.WriteString("\033[0m")
					res.WriteString(line[vEnd+1:])
				} else {
					res.WriteString(line)
				}
			}
		} else {
			res.WriteString(line)
		}
		if i < len(lines)-1 {
			res.WriteString("\r\n")
		}
	}
	return res.String()
}

func doDownload(client *http.Client, req *http.Request) {
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %v", err)
	}
	defer resp.Body.Close()

	fmt.Printf("\033[95m%s\033[0m \033[92m%s\033[0m\r\n", resp.Proto, resp.Status)
	var keys []string
	for k := range resp.Header {
